sys_ui_page.client_script:
function confirmation() {
    var userInput = document.getElementById('userInput').value; //from HTML to client
    var userRec = GlideDialogWindow.get().getPreference('sysparm_currentRec') ? GlideDialogWindow.get().getPreference('sysparm_currentRec') : g_user.userName; // from form client to here
    var otpLength = userInput.length;



    if ((userInput) && (otpLength == 6)) {

        //validating if entered OTP is equal to generated OTP
        validateOTP(userInput, userRec);
        //validating if entered OTP is equal to generated OTP

        GlideDialogWindow.get().destroy(); // Close the modal
    } else {
        document.getElementById('userInput').value = "";
        alert('Please Enter the 6 digit OTP sent to your registered Email ID.');
    }
}


function cancellation() {
    GlideDialogWindow.get().destroy();
}


function validateOTP(userInput, userRec) {

    var getUserData = new GlideRecord('sys_user');
    getUserData.get(userRec);

    var enteredOTP = userInput;
    var generatedOTP = getUserData.correlation_id;

    if (enteredOTP == generatedOTP) {

        getUserData.setValue('x_938076_now_utils_otp_validation', 'OTP Validation Successful');
        getUserData.update();

        //alert('OTP Matched');
    } else {

        getUserData.setValue('x_938076_now_utils_otp_validation', 'OTP Validation Un-Successful');
        getUserData.update();
        // alert('OTP Not Matching');
    }
}
